using System;
using System.Drawing;
using System.Windows.Forms;

namespace MECCG_Deck_Builder
{
    public sealed class AddTagDialog : Form
    {
        private readonly CardFilterService _filterService;
        private readonly ComboBox _cmbKey;
        private readonly ComboBox _cmbValue;

        public string SelectedKey => _cmbKey.Text.Trim();
        public string SelectedValue => _cmbValue.Text.Trim();

        private AddTagDialog(string cardName, CardFilterService filterService)
        {
            _filterService = filterService ?? throw new ArgumentNullException(nameof(filterService));

            Text = "Assign Custom Tag";
            ClientSize = new Size(380, 190);
            FormBorderStyle = FormBorderStyle.FixedDialog;
            MaximizeBox = false;
            MinimizeBox = false;
            StartPosition = FormStartPosition.CenterParent;
            ShowInTaskbar = false;
            Font = new Font("Segoe UI", 9.0f);

            var lblHeader = new Label
            {
                Text = $"Assign tag to card: {cardName}",
                Location = new Point(12, 12),
                Size = new Size(356, 20),
                Font = new Font("Segoe UI", 9.0f, FontStyle.Bold)
            };

            var lblKey = new Label
            {
                Text = "Category:",
                Location = new Point(12, 40),
                Size = new Size(356, 16)
            };

            _cmbKey = new ComboBox
            {
                Location = new Point(12, 58),
                Size = new Size(356, 23),
                DropDownStyle = ComboBoxStyle.DropDown,
                AutoCompleteMode = AutoCompleteMode.SuggestAppend,
                AutoCompleteSource = AutoCompleteSource.ListItems
            };

            var lblValue = new Label
            {
                Text = "Tag:",
                Location = new Point(12, 90),
                Size = new Size(356, 16)
            };

            _cmbValue = new ComboBox
            {
                Location = new Point(12, 108),
                Size = new Size(356, 23),
                DropDownStyle = ComboBoxStyle.DropDown,
                AutoCompleteMode = AutoCompleteMode.SuggestAppend,
                AutoCompleteSource = AutoCompleteSource.ListItems
            };

            var btnOk = new Button
            {
                Text = "Assign Tag",
                Location = new Point(190, 148),
                Size = new Size(90, 26)
            };
            btnOk.Click += BtnOk_Click;

            var btnCancel = new Button
            {
                Text = "Cancel",
                Location = new Point(288, 148),
                Size = new Size(80, 26),
                DialogResult = DialogResult.Cancel
            };

            Controls.AddRange([lblHeader, lblKey, _cmbKey, lblValue, _cmbValue, btnOk, btnCancel]);
            AcceptButton = btnOk;
            CancelButton = btnCancel;

            PopulateKeys();

            _cmbKey.SelectedIndexChanged += (s, e) => PopulateValuesForKey();
            _cmbKey.TextChanged += (s, e) => PopulateValuesForKey();

            Shown += (s, e) => _cmbKey.Focus();
        }

        private void PopulateKeys()
        {
            _cmbKey.Items.Clear();
            var keys = _filterService.GetCustomKeyNames();
            foreach (var k in keys)
            {
                if (!string.IsNullOrWhiteSpace(k))
                {
                    _cmbKey.Items.Add(k);
                }
            }

            if (_cmbKey.Items.Count > 0)
            {
                _cmbKey.SelectedIndex = 0;
            }
        }

        private void PopulateValuesForKey()
        {
            string key = _cmbKey.Text.Trim();
            _cmbValue.Items.Clear();
            if (string.IsNullOrWhiteSpace(key)) return;

            var values = _filterService.GetCustomKeyValues(key);
            foreach (var v in values)
            {
                if (!string.IsNullOrWhiteSpace(v))
                {
                    _cmbValue.Items.Add(v);
                }
            }
        }

        private void BtnOk_Click(object sender, EventArgs e)
        {
            if (string.IsNullOrWhiteSpace(SelectedKey))
            {
                MessageBox.Show(this, "Please enter or select a category.", "Assign Tag", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                _cmbKey.Focus();
                return;
            }

            if (string.IsNullOrWhiteSpace(SelectedValue))
            {
                MessageBox.Show(this, "Please enter or select a tag.", "Assign Tag", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                _cmbValue.Focus();
                return;
            }

            DialogResult = DialogResult.OK;
        }

        public static (string Key, string Value)? Show(IWin32Window owner, string cardName, CardFilterService filterService)
        {
            using var dlg = new AddTagDialog(cardName, filterService);
            if (dlg.ShowDialog(owner) == DialogResult.OK)
            {
                return (dlg.SelectedKey, dlg.SelectedValue);
            }
            return null;
        }
    }
}

using System;
using System.Collections.Generic;

namespace MECCG_Deck_Builder
{
    public sealed class Card
    {
        public string Id { get; init; } = string.Empty;
        public string Set { get; init; } = string.Empty;
        public string FullCode { get; init; } = string.Empty;
        public string Name { get; init; } = string.Empty;
        public string Text { get; init; } = string.Empty;
        public string ImageName { get; init; } = string.Empty;

        // Cardnum attributes
        public string Primary { get; init; } = string.Empty;
        public string Alignment { get; init; } = string.Empty;
        public string Artist { get; init; } = string.Empty;
        public string Skill { get; init; } = string.Empty;
        public string MPs { get; init; } = string.Empty;
        public string Mind { get; init; } = string.Empty;
        public string Direct { get; init; } = string.Empty;
        public string Prowess { get; init; } = string.Empty;
        public string Body { get; init; } = string.Empty;
        public string Corruption { get; init; } = string.Empty;
        public string Home { get; init; } = string.Empty;
        public string Unique { get; init; } = string.Empty;
        public string Secondary { get; init; } = string.Empty;
        public string Race { get; init; } = string.Empty;
        public string Site { get; init; } = string.Empty;
        public string Region { get; init; } = string.Empty;
        public string Playable { get; init; } = string.Empty;
        public string GoldRing { get; init; } = string.Empty;
        public string GreaterItem { get; init; } = string.Empty;
        public string MajorItem { get; init; } = string.Empty;
        public string MinorItem { get; init; } = string.Empty;
        public string Information { get; init; } = string.Empty;
        public string Palantiri { get; init; } = string.Empty;
        public string Scroll { get; init; } = string.Empty;
        public string Hoard { get; init; } = string.Empty;
        public string Haven { get; init; } = string.Empty;
        public string Strikes { get; init; } = string.Empty;
        public string Specific { get; init; } = string.Empty;

        // Additional metadata
        public bool Dreamcard { get; init; }
        public bool Released { get; init; }
        public bool IceErrata { get; init; }

        // Dynamic attribute map for filter lookup
        private readonly Dictionary<string, string> _attributes = new(StringComparer.OrdinalIgnoreCase);

        public Card() { }

        public void SetAttribute(string key, string value)
        {
            if (!string.IsNullOrEmpty(key))
            {
                _attributes[key] = value ?? string.Empty;
            }
        }

        public string GetAttribute(string key)
        {
            if (string.IsNullOrEmpty(key))
            {
                return string.Empty;
            }

            if (_attributes.TryGetValue(key, out string value))
            {
                return value;
            }

            return key.ToLowerInvariant() switch
            {
                "id" => Id,
                "set" => Set,
                "fullcode" => FullCode,
                "cardname" or "name" => Name,
                "text" => Text,
                "imagename" => ImageName,
                "primary" => Primary,
                "alignment" => Alignment,
                "artist" => Artist,
                "skill" => Skill,
                "mps" => MPs,
                "mind" => Mind,
                "direct" => Direct,
                "prowess" => Prowess,
                "body" => Body,
                "corruption" => Corruption,
                "home" => Home,
                "unique" => Unique,
                "secondary" => Secondary,
                "race" => Race,
                "site" => Site,
                "region" => Region,
                "playable" => Playable,
                "goldring" => GoldRing,
                "greateritem" => GreaterItem,
                "majoritem" => MajorItem,
                "minoritem" => MinorItem,
                "information" => Information,
                "palantiri" => Palantiri,
                "scroll" => Scroll,
                "hoard" => Hoard,
                "haven" => Haven,
                "strikes" => Strikes,
                "specific" => Specific,
                _ => string.Empty
            };
        }

        public bool TryGetAttribute(string key, out string value)
        {
            value = GetAttribute(key);
            return !string.IsNullOrEmpty(value);
        }

        public override string ToString() => $"{Name} ({Set})";
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using NaturalSort.Extension;
using Newtonsoft.Json;

namespace MECCG_Deck_Builder
{
    public sealed class CardCatalogService
    {
        private static readonly HttpClient s_httpClient = new();

        public static readonly string[] FilterKeys =
        [
            "Primary", "Alignment", "Artist", "Skill", "MPs", "Mind", "Direct", "Prowess", "Body",
            "Corruption", "Home", "Unique", "Secondary", "Race", "Site", "Region", "Playable", "GoldRing", "GreaterItem",
            "MajorItem", "MinorItem", "Information", "Palantiri", "Scroll", "Hoard", "Haven", "Strikes", "Specific"
        ];

        private readonly List<Card> _cards = [];
        private readonly Dictionary<string, Card> _cardsById = new(StringComparer.OrdinalIgnoreCase);
        private readonly List<CardSet> _sets = [];
        private readonly Dictionary<string, List<string>> _filterOptions = new(StringComparer.OrdinalIgnoreCase);

        public IReadOnlyList<Card> Cards => _cards;
        public IReadOnlyDictionary<string, Card> CardsById => _cardsById;
        public IReadOnlyList<CardSet> Sets => _sets;

        public event EventHandler<string> WarningOccurred;

        public Card GetCardById(string cardId)
        {
            if (!string.IsNullOrEmpty(cardId) && _cardsById.TryGetValue(cardId, out var card))
            {
                return card;
            }
            return null;
        }

        public IReadOnlyList<string> GetFilterKeys()
        {
            var keys = new List<string> { "" }; // Index 0 is blank
            var sortedKeys = new List<string>(_filterOptions.Keys);
            sortedKeys.Sort(StringComparer.Ordinal);
            keys.AddRange(sortedKeys);
            return keys;
        }

        public IReadOnlyList<string> GetFilterValues(string key)
        {
            if (!string.IsNullOrEmpty(key) && _filterOptions.TryGetValue(key, out var values))
            {
                return values;
            }
            return [""]; // If key is blank, values list is just blank
        }

        public async Task InitializeAsync(CancellationToken cancellationToken = default)
        {
            await LoadSetsAsync(cancellationToken).ConfigureAwait(false);
            await LoadCardsAsync(cancellationToken).ConfigureAwait(false);
        }

        private async Task LoadSetsAsync(CancellationToken cancellationToken)
        {
            string json = null;
            List<CardnumSet> rawSets = null;

            // 1. Try download from GitHub
            try
            {
                json = await s_httpClient.GetStringAsync(Constants.CardnumSetsURL, cancellationToken).ConfigureAwait(false);
                rawSets = JsonConvert.DeserializeObject<List<CardnumSet>>(json);
                try
                {
                    await File.WriteAllTextAsync(Constants.CardnumSetsFile, json, cancellationToken).ConfigureAwait(false);
                }
                catch (Exception)
                {
                    WarningOccurred?.Invoke(this, Messages.GetMsgBoxText("ImportCardnumSetInfo3"));
                }
            }
            catch (Exception)
            {
                // 2. Fallback to local file
                try
                {
                    json = await File.ReadAllTextAsync(Constants.CardnumSetsFile, cancellationToken).ConfigureAwait(false);
                    rawSets = JsonConvert.DeserializeObject<List<CardnumSet>>(json);
                    WarningOccurred?.Invoke(this, Messages.GetMsgBoxText("ImportCardnumSetInfo1"));
                }
                catch (Exception)
                {
                    // 3. Emergency fallback
                    _sets.Clear();
                    _sets.Add(new CardSet
                    {
                        Code = "METW",
                        Name = "The Wizards",
                        Format = "General",
                        Position = 1,
                        Dreamcards = false,
                        Released = true
                    });
                    WarningOccurred?.Invoke(this, Messages.GetMsgBoxText("ImportCardnumSetInfo2"));
                    return;
                }
            }

            _sets.Clear();
            if (rawSets != null)
            {
                foreach (var s in rawSets)
                {
                    _sets.Add(new CardSet
                    {
                        Code = s.Code,
                        Name = s.Name,
                        Format = s.Format,
                        Position = s.Position,
                        Dreamcards = s.Dreamcards,
                        Released = s.Released
                    });
                }
            }
        }

        private async Task LoadCardsAsync(CancellationToken cancellationToken)
        {
            string json = null;
            List<CardnumCard> rawCards = null;

            // 1. Try download from GitHub
            try
            {
                json = await s_httpClient.GetStringAsync(Constants.CardnumCardsURL, cancellationToken).ConfigureAwait(false);
                rawCards = JsonConvert.DeserializeObject<List<CardnumCard>>(json);
                try
                {
                    await File.WriteAllTextAsync(Constants.CardnumCardsFile, json, cancellationToken).ConfigureAwait(false);
                }
                catch (Exception)
                {
                    WarningOccurred?.Invoke(this, Messages.GetMsgBoxText("ImportCardnumCardInfo3"));
                }
            }
            catch (Exception)
            {
                // 2. Fallback to local file
                try
                {
                    json = await File.ReadAllTextAsync(Constants.CardnumCardsFile, cancellationToken).ConfigureAwait(false);
                    rawCards = JsonConvert.DeserializeObject<List<CardnumCard>>(json);
                    WarningOccurred?.Invoke(this, Messages.GetMsgBoxText("ImportCardnumCardInfo1"));
                }
                catch (Exception)
                {
                    // 3. Emergency fallback: Single default card
                    var emergencyCard = new Card
                    {
                        Id = "0",
                        Set = "METW",
                        FullCode = "Adrazar (TW)",
                        Name = "Adrazar",
                        Alignment = "Hero",
                        ImageName = "metw_adrazar.jpg",
                        Released = true
                    };
                    _cards.Clear();
                    _cardsById.Clear();
                    _cards.Add(emergencyCard);
                    _cardsById[emergencyCard.Id] = emergencyCard;
                    WarningOccurred?.Invoke(this, Messages.GetMsgBoxText("ImportCardnumCardInfo2"));
                    return;
                }
            }

            InitializeFilterKeys();

            _cards.Clear();
            _cardsById.Clear();

            int idCounter = 0;
            if (rawCards != null)
            {
                foreach (var raw in rawCards)
                {
                    if (!raw.Dreamcard && !raw.Released)
                    {
                        continue;
                    }

                    string imageName = raw.Ice_errata == true ? $"ice-{raw.ImageName}" : raw.ImageName;

                    var card = new Card
                    {
                        Id = (idCounter++).ToString(),
                        Set = raw.Set ?? string.Empty,
                        FullCode = raw.FullCode ?? string.Empty,
                        Name = raw.NameEN ?? string.Empty,
                        Text = raw.Text ?? string.Empty,
                        ImageName = imageName ?? string.Empty,
                        Primary = raw.Primary ?? string.Empty,
                        Alignment = raw.Alignment ?? string.Empty,
                        Artist = raw.Artist ?? string.Empty,
                        Skill = raw.Skill ?? string.Empty,
                        MPs = raw.MPs ?? string.Empty,
                        Mind = raw.Mind ?? string.Empty,
                        Direct = raw.Direct ?? string.Empty,
                        Prowess = raw.Prowess?.ToString() ?? string.Empty,
                        Body = raw.Body ?? string.Empty,
                        Corruption = raw.Corruption ?? string.Empty,
                        Home = raw.Home ?? string.Empty,
                        Unique = raw.Unique ?? string.Empty,
                        Secondary = raw.Secondary ?? string.Empty,
                        Race = raw.Race ?? string.Empty,
                        Site = raw.Site ?? string.Empty,
                        Region = raw.Region ?? string.Empty,
                        Playable = raw.Playable ?? string.Empty,
                        GoldRing = raw.GoldRing ?? string.Empty,
                        GreaterItem = raw.GreaterItem ?? string.Empty,
                        MajorItem = raw.MajorItem ?? string.Empty,
                        MinorItem = raw.MinorItem ?? string.Empty,
                        Information = raw.Information ?? string.Empty,
                        Palantiri = raw.Palantiri ?? string.Empty,
                        Scroll = raw.Scroll ?? string.Empty,
                        Hoard = raw.Hoard ?? string.Empty,
                        Haven = raw.Haven ?? string.Empty,
                        Strikes = raw.Strikes?.ToString() ?? string.Empty,
                        Specific = raw.Specific ?? string.Empty,
                        Dreamcard = raw.Dreamcard,
                        Released = raw.Released,
                        IceErrata = raw.Ice_errata == true
                    };

                    foreach (string key in FilterKeys)
                    {
                        string val = card.GetAttribute(key);
                        card.SetAttribute(key, val);
                        RegisterFilterValue(key, val);
                    }

                    _cards.Add(card);
                    _cardsById[card.Id] = card;
                }
            }
        }

        private void InitializeFilterKeys()
        {
            _filterOptions.Clear();
            foreach (string key in FilterKeys)
            {
                _filterOptions[key] = [""];
            }
        }

        private void RegisterFilterValue(string key, string value)
        {
            if (string.IsNullOrEmpty(value) || !_filterOptions.TryGetValue(key, out var list))
            {
                return;
            }

            if (key != "Skill")
            {
                if (!list.Contains(value))
                {
                    list.Add(value);
                    if (list.Count > 2)
                    {
                        list.Sort(1, list.Count - 1, StringComparison.OrdinalIgnoreCase.WithNaturalSort());
                    }
                }
            }
            else
            {
                string[] words = value.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);
                foreach (string word in words)
                {
                    if (!list.Contains(word))
                    {
                        list.Add(word);
                        if (list.Count > 2)
                        {
                            list.Sort(1, list.Count - 1, StringComparison.OrdinalIgnoreCase.WithNaturalSort());
                        }
                    }
                }
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using NaturalSort.Extension;

namespace MECCG_Deck_Builder
{
    public sealed class CardFilterService
    {
        // Custom user filters
        private readonly List<List<string>> _customFilters = []; // [0] = keyName, [1..] = values
        private readonly Dictionary<string, Dictionary<string, string>> _cardCustomTags = new(StringComparer.OrdinalIgnoreCase); // cardId -> (tagKey -> tagValue)

        public IReadOnlyList<List<string>> CustomFilters => _customFilters;
        public IReadOnlyDictionary<string, Dictionary<string, string>> CardCustomTags => _cardCustomTags;

        #region CUSTOM_FILTER_MANAGEMENT

        public List<string> GetCustomKeyNames()
        {
            var names = new List<string> { "" }; // Index 0 is blank
            var sortedNames = _customFilters.Select(f => f[0]).ToList();
            sortedNames.Sort(StringComparer.Ordinal);
            names.AddRange(sortedNames);
            return names;
        }

        public List<string> GetCustomKeyValues(string keyName)
        {
            var values = new List<string> { "" };
            if (string.IsNullOrWhiteSpace(keyName))
            {
                return values;
            }

            int index = _customFilters.FindIndex(f => string.Equals(f[0], keyName, StringComparison.OrdinalIgnoreCase));
            if (index >= 0)
            {
                for (int i = 1; i < _customFilters[index].Count; i++)
                {
                    values.Add(_customFilters[index][i]);
                }
            }
            return values;
        }

        public void AddCustomKeyName(string keyName)
        {
            if (string.IsNullOrWhiteSpace(keyName) || _customFilters.Exists(f => string.Equals(f[0], keyName, StringComparison.OrdinalIgnoreCase)))
            {
                return;
            }

            _customFilters.Add([keyName]);
            _customFilters.Sort((a, b) => string.Compare(a[0], b[0], StringComparison.Ordinal));
        }

        public void AddCustomKeyValue(string keyName, string value)
        {
            if (string.IsNullOrWhiteSpace(keyName) || string.IsNullOrWhiteSpace(value))
            {
                return;
            }

            int index = _customFilters.FindIndex(f => string.Equals(f[0], keyName, StringComparison.OrdinalIgnoreCase));
            if (index == -1)
            {
                AddCustomKeyName(keyName);
                index = _customFilters.FindIndex(f => string.Equals(f[0], keyName, StringComparison.OrdinalIgnoreCase));
            }

            if (index != -1 && !_customFilters[index].Contains(value, StringComparer.OrdinalIgnoreCase))
            {
                _customFilters[index].Add(value);
                if (_customFilters[index].Count > 2)
                {
                    _customFilters[index].Sort(1, _customFilters[index].Count - 1, StringComparison.OrdinalIgnoreCase.WithNaturalSort());
                }
            }
        }

        public void RenameCustomKeyName(string oldKeyName, string newKeyName)
        {
            if (string.IsNullOrWhiteSpace(oldKeyName) || string.IsNullOrWhiteSpace(newKeyName) ||
                string.Equals(oldKeyName, newKeyName, StringComparison.OrdinalIgnoreCase))
            {
                return;
            }

            int index = _customFilters.FindIndex(f => string.Equals(f[0], oldKeyName, StringComparison.OrdinalIgnoreCase));
            if (index >= 0)
            {
                _customFilters[index][0] = newKeyName;
                _customFilters.Sort((a, b) => string.Compare(a[0], b[0], StringComparison.Ordinal));
            }

            foreach (var tags in _cardCustomTags.Values)
            {
                if (tags.TryGetValue(oldKeyName, out string val))
                {
                    tags.Remove(oldKeyName);
                    tags[newKeyName] = val;
                }
            }
        }

        public void RenameCustomKeyValue(string keyName, string oldValue, string newValue)
        {
            if (string.IsNullOrWhiteSpace(keyName) || string.IsNullOrWhiteSpace(oldValue) ||
                string.IsNullOrWhiteSpace(newValue) || string.Equals(oldValue, newValue, StringComparison.OrdinalIgnoreCase))
            {
                return;
            }

            int index = _customFilters.FindIndex(f => string.Equals(f[0], keyName, StringComparison.OrdinalIgnoreCase));
            if (index >= 0)
            {
                for (int i = 1; i < _customFilters[index].Count; i++)
                {
                    if (string.Equals(_customFilters[index][i], oldValue, StringComparison.OrdinalIgnoreCase))
                    {
                        _customFilters[index][i] = newValue;
                        break;
                    }
                }

                if (_customFilters[index].Count > 2)
                {
                    _customFilters[index].Sort(1, _customFilters[index].Count - 1, StringComparison.OrdinalIgnoreCase.WithNaturalSort());
                }
            }

            foreach (var tags in _cardCustomTags.Values)
            {
                if (tags.TryGetValue(keyName, out string existingVal) &&
                    string.Equals(existingVal, oldValue, StringComparison.OrdinalIgnoreCase))
                {
                    tags[keyName] = newValue;
                }
            }
        }

        public void DeleteCustomKeyName(string keyName)
        {
            int index = _customFilters.FindIndex(f => string.Equals(f[0], keyName, StringComparison.OrdinalIgnoreCase));
            if (index >= 0)
            {
                _customFilters.RemoveAt(index);
            }

            foreach (var tags in _cardCustomTags.Values)
            {
                tags.Remove(keyName);
            }
        }

        public void DeleteCustomKeyValue(string keyName, string value)
        {
            int index = _customFilters.FindIndex(f => string.Equals(f[0], keyName, StringComparison.OrdinalIgnoreCase));
            if (index >= 0)
            {
                _customFilters[index].RemoveAll(v => string.Equals(v, value, StringComparison.OrdinalIgnoreCase));
            }

            foreach (var tags in _cardCustomTags.Values)
            {
                if (tags.TryGetValue(keyName, out string existing) && string.Equals(existing, value, StringComparison.OrdinalIgnoreCase))
                {
                    tags.Remove(keyName);
                }
            }
        }

        public void SetCardCustomTag(string cardId, string keyName, string value)
        {
            if (string.IsNullOrEmpty(cardId) || string.IsNullOrEmpty(keyName))
            {
                return;
            }

            if (!_cardCustomTags.TryGetValue(cardId, out var tags))
            {
                tags = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                _cardCustomTags[cardId] = tags;
            }

            tags[keyName] = value ?? string.Empty;

            if (!string.IsNullOrWhiteSpace(value))
            {
                AddCustomKeyValue(keyName, value);
            }
        }

        public void DeleteCardCustomTag(string cardId, string keyName)
        {
            if (_cardCustomTags.TryGetValue(cardId, out var tags))
            {
                tags.Remove(keyName);
                if (tags.Count == 0)
                {
                    _cardCustomTags.Remove(cardId);
                }
            }
        }

        public List<KeyValuePair<string, string>> GetCardCustomFilterPairs(string cardId)
        {
            var pairs = new List<KeyValuePair<string, string>>();
            if (_cardCustomTags.TryGetValue(cardId, out var tags))
            {
                foreach (var kvp in tags)
                {
                    pairs.Add(new KeyValuePair<string, string>(kvp.Key, kvp.Value));
                }
            }
            return pairs;
        }

        public List<string> GetCardCustomKeyNames(string cardId)
        {
            if (_cardCustomTags.TryGetValue(cardId, out var tags))
            {
                return [.. tags.Keys];
            }
            return [];
        }

        public void LoadCustomFilters(List<List<string>> filters, List<SortedDictionary<string, string>> cardMappings)
        {
            _customFilters.Clear();
            _cardCustomTags.Clear();

            if (filters != null)
            {
                foreach (var f in filters)
                {
                    _customFilters.Add([.. f]);
                }
            }

            if (cardMappings != null)
            {
                foreach (var dict in cardMappings)
                {
                    if (dict.TryGetValue("id", out string cardId))
                    {
                        var tags = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                        foreach (var kvp in dict)
                        {
                            if (!string.Equals(kvp.Key, "id", StringComparison.OrdinalIgnoreCase))
                            {
                                tags[kvp.Key] = kvp.Value;
                            }
                        }
                        _cardCustomTags[cardId] = tags;
                    }
                }
            }
        }

        #endregion

        #region FILTER_AND_FACET_EVALUATION

        public static bool MatchesCardnumCriterion(Card card, string key, string value)
        {
            if (string.IsNullOrWhiteSpace(key) || string.IsNullOrWhiteSpace(value))
            {
                return true;
            }

            string cardValue = card.GetAttribute(key);
            if (string.IsNullOrEmpty(cardValue))
            {
                return false;
            }

            if (string.Equals(key, "Skill", StringComparison.OrdinalIgnoreCase))
            {
                string[] skills = cardValue.Split([' ', '/'], StringSplitOptions.RemoveEmptyEntries);
                foreach (var s in skills)
                {
                    if (string.Equals(s, value, StringComparison.OrdinalIgnoreCase))
                    {
                        return true;
                    }
                }
                return false;
            }

            return string.Equals(cardValue.Trim(), value.Trim(), StringComparison.OrdinalIgnoreCase);
        }

        public bool MatchesCustomCriterion(string cardId, string key, string value)
        {
            if (string.IsNullOrWhiteSpace(key) || string.IsNullOrWhiteSpace(value))
            {
                return true;
            }

            if (!_cardCustomTags.TryGetValue(cardId, out var tags))
            {
                return false;
            }

            if (!tags.TryGetValue(key, out string tagVal) || string.IsNullOrEmpty(tagVal))
            {
                return false;
            }

            return string.Equals(tagVal.Trim(), value.Trim(), StringComparison.OrdinalIgnoreCase);
        }

        public bool MatchesCriteria(Card card, IReadOnlyList<FilterCriterion> criteria)
        {
            if (criteria == null || criteria.Count == 0)
            {
                return true;
            }

            foreach (var c in criteria)
            {
                if (!c.IsActive)
                {
                    continue;
                }

                if (c.Type == FilterType.Cardnum)
                {
                    if (!MatchesCardnumCriterion(card, c.Key, c.Value))
                    {
                        return false;
                    }
                }
                else
                {
                    if (!MatchesCustomCriterion(card.Id, c.Key, c.Value))
                    {
                        return false;
                    }
                }
            }

            return true;
        }

        public List<Card> Filter(
            IEnumerable<Card> sourceCards,
            ISet<string> selectedSets,
            IReadOnlyList<FilterCriterion> criteria)
        {
            var result = new List<Card>();

            foreach (var card in sourceCards)
            {
                if (selectedSets != null && !selectedSets.Contains(card.Set))
                {
                    continue;
                }

                if (!MatchesCriteria(card, criteria))
                {
                    continue;
                }

                result.Add(card);
            }

            result.Sort((a, b) => string.Compare(a.Name, b.Name, StringComparison.Ordinal));
            return result;
        }

        public List<string> GetAvailableValues(
            IEnumerable<Card> sourceCards,
            ISet<string> selectedSets,
            IReadOnlyList<FilterCriterion> otherCriteria,
            FilterType targetType,
            string targetKey)
        {
            var result = new List<string> { "" };

            if (string.IsNullOrWhiteSpace(targetKey))
            {
                return result;
            }

            var distinctValues = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            // For custom taxonomy filters, always include all values defined in the taxonomy for this key
            if (targetType == FilterType.Custom)
            {
                var taxonomyValues = GetCustomKeyValues(targetKey);
                foreach (var val in taxonomyValues)
                {
                    if (!string.IsNullOrWhiteSpace(val))
                    {
                        distinctValues.Add(val.Trim());
                    }
                }
            }

            foreach (var card in sourceCards)
            {
                if (selectedSets != null && !selectedSets.Contains(card.Set))
                {
                    continue;
                }

                if (!MatchesCriteria(card, otherCriteria))
                {
                    continue;
                }

                if (targetType == FilterType.Cardnum)
                {
                    string attr = card.GetAttribute(targetKey);
                    if (string.IsNullOrWhiteSpace(attr))
                    {
                        continue;
                    }

                    if (string.Equals(targetKey, "Skill", StringComparison.OrdinalIgnoreCase))
                    {
                        string[] words = attr.Split([' ', '/'], StringSplitOptions.RemoveEmptyEntries);
                        foreach (string word in words)
                        {
                            distinctValues.Add(word.Trim());
                        }
                    }
                    else
                    {
                        distinctValues.Add(attr.Trim());
                    }
                }
                else
                {
                    if (_cardCustomTags.TryGetValue(card.Id, out var tags) &&
                        tags.TryGetValue(targetKey, out string tagVal) &&
                        !string.IsNullOrWhiteSpace(tagVal))
                    {
                        distinctValues.Add(tagVal.Trim());
                    }
                }
            }

            var sortedList = distinctValues.ToList();
            sortedList.Sort(StringComparison.OrdinalIgnoreCase.WithNaturalSort());
            result.AddRange(sortedList);
            return result;
        }

        #endregion
    }
}

using Microsoft.Extensions.Caching.Memory;
using System;
using System.Drawing;
using System.IO;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

namespace MECCG_Deck_Builder
{
    public class CardImageCache
    {
        // HttpClient should be a shared, static, or long-lived instance
        private static readonly HttpClient s_httpClient = new();

        private readonly MemoryCache Cache = new(new MemoryCacheOptions()
        {
            SizeLimit = 10000
        });

        #region ASYNC_METHODS

        /// <summary>
        /// Asynchronously retrieves an image from in-memory cache, local disk, or remote Cardnum endpoint.
        /// </summary>
        internal async Task<Bitmap> GetOrCreateAsync(string key, string setFolder, string imageName, CancellationToken cancellationToken = default)
        {
            // 1. Check in-memory cache
            if (Cache.TryGetValue(key, out Bitmap cacheEntry))
            {
                return cacheEntry;
            }

            string filePath = Path.Combine(setFolder, imageName);

            // 2. Fall back to local disk asynchronously
            if (File.Exists(filePath))
            {
                cacheEntry = await LoadImageNonLockingAsync(filePath, cancellationToken).ConfigureAwait(false);
            }
            else
            {
                // 3. Fall back to remote network download asynchronously
                cacheEntry = await CreateItemAsync(key, cancellationToken).ConfigureAwait(false);

                if (cacheEntry != null && !cancellationToken.IsCancellationRequested)
                {
                    try
                    {
                        if (!Directory.Exists(setFolder))
                        {
                            Directory.CreateDirectory(setFolder);
                        }
                        cacheEntry.Save(filePath);
                    }
                    catch (Exception)
                    {
                        // Disk write failure should not prevent using the downloaded in-memory image
                    }
                }
            }

            // 4. Populate MemoryCache on disk hit or network download
            if (cacheEntry != null && !cancellationToken.IsCancellationRequested)
            {
                var cacheEntryOptions = new MemoryCacheEntryOptions()
                    .SetSize(1);

                Cache.Set(key, cacheEntry, cacheEntryOptions);
            }

            return cacheEntry;
        }

        /// <summary>
        /// Asynchronously downloads card image bytes and converts them into a non-locking Bitmap.
        /// </summary>
        internal static async Task<Bitmap> CreateItemAsync(string key, CancellationToken cancellationToken = default)
        {
            try
            {
                byte[] imageBytes = await s_httpClient.GetByteArrayAsync(key, cancellationToken).ConfigureAwait(false);
                using var ms = new MemoryStream(imageBytes);
                using var img = Image.FromStream(ms);
                return new Bitmap(img);
            }
            catch (OperationCanceledException)
            {
                return null;
            }
            catch (HttpRequestException)
            {
                return null;
            }
            catch (Exception)
            {
                return null;
            }
        }

        /// <summary>
        /// Reads image bytes into memory asynchronously before creating a Bitmap so GDI+ does not lock the file on disk.
        /// </summary>
        private static async Task<Bitmap> LoadImageNonLockingAsync(string filePath, CancellationToken cancellationToken = default)
        {
            try
            {
                byte[] bytes = await File.ReadAllBytesAsync(filePath, cancellationToken).ConfigureAwait(false);
                using var ms = new MemoryStream(bytes);
                using var img = Image.FromStream(ms);
                return new Bitmap(img);
            }
            catch (Exception)
            {
                return null;
            }
        }

        #endregion

        #region SYNCHRONOUS_METHODS

        internal Bitmap GetOrCreate(string key, string setFolder, string imageName)
        {
            if (Cache.TryGetValue(key, out Bitmap cacheEntry))
            {
                return cacheEntry;
            }

            string filePath = Path.Combine(setFolder, imageName);

            if (File.Exists(filePath))
            {
                cacheEntry = LoadImageNonLocking(filePath);
            }
            else
            {
                cacheEntry = CreateItem(key);

                if (cacheEntry != null)
                {
                    try
                    {
                        if (!Directory.Exists(setFolder))
                        {
                            Directory.CreateDirectory(setFolder);
                        }
                        cacheEntry.Save(filePath);
                    }
                    catch (Exception)
                    {
                    }
                }
            }

            if (cacheEntry != null)
            {
                var cacheEntryOptions = new MemoryCacheEntryOptions()
                    .SetSize(1);

                Cache.Set(key, cacheEntry, cacheEntryOptions);
            }

            return cacheEntry;
        }

        private static Bitmap LoadImageNonLocking(string filePath)
        {
            try
            {
                byte[] bytes = File.ReadAllBytes(filePath);
                using var ms = new MemoryStream(bytes);
                using var img = Image.FromStream(ms);
                return new Bitmap(img);
            }
            catch (Exception)
            {
                return null;
            }
        }

        internal static Bitmap CreateItem(string key)
        {
            try
            {
                byte[] imageBytes = s_httpClient.GetByteArrayAsync(key).Result;
                using var ms = new MemoryStream(imageBytes);
                using var img = Image.FromStream(ms);
                return new Bitmap(img);
            }
            catch (Exception)
            {
                return null;
            }
        }

        #endregion
    }
}

